import React, { useState, useEffect } from 'https://cdn.jsdelivr.net/npm/react@18.2.0/+esm';
import ReactDOM from 'https://cdn.jsdelivr.net/npm/react-dom@18.2.0/+esm';
const parseAppsmithModel = modelRaw => {
  if (!modelRaw) return {};
  let parsed = modelRaw;
  if (typeof modelRaw === 'string') {
    try {
      parsed = JSON.parse(modelRaw);
    } catch (e) {
      console.warn('Unable to parse Appsmith model:', e);
    }
  }
  return parsed || {};
};
function CommercialEvalHeader() {
  const [modelData, setModelData] = useState(() => parseAppsmithModel(window.appsmith?.model));
  useEffect(() => {
    if (window.appsmith?.onModelChange) {
      window.appsmith.onModelChange(m => {
        if (!m) return;
        setModelData(parseAppsmithModel(m));
      });
    }
  }, []);

  /* =========================================================
  HEADER DATA
  ========================================================= */
  const phaseBadge = modelData.phaseBadge || 'STAGE 08 - COMMERCIAL EVALUATION';
  const roundPill = modelData.roundPill || '';
  const title = modelData.title || 'Consulting Services';
  const subtitle = modelData.subtitle || 'RFQ-2026-000567 · Commercial evaluation';
  const rightBadge = modelData.rightBadge || 'Evaluation completed';

  /* =========================================================
  CONVERSATION HISTORY
  ========================================================= */
  const handleConversationHistory = () => {
    if (window.appsmith) {
      window.appsmith.triggerEvent('onConversationHistory');
    }
  };

  /* =========================================================
  UI
  ========================================================= */
  return React.createElement('div', {
    className: 'stage-header-container'
  }, /* LEFT SIDE */
  React.createElement('div', {
    className: 'stage-header-left'
  }, /* STAGE LABEL */
  React.createElement('div', {
    className: 'stage-breadcrumb-row'
  }, React.createElement('span', {
    className: 'stage-phase-badge'
  }, phaseBadge), roundPill ? React.createElement('span', {
    className: 'stage-round-pill'
  }, roundPill) : null), /* TITLE */
  React.createElement('h1', {
    className: 'stage-title'
  }, title), /* SUBTITLE */
  React.createElement('p', {
    className: 'stage-subtitle'
  }, subtitle)), /* RIGHT SIDE */
  React.createElement('div', {
    className: 'stage-header-right'
  }, /* CONVERSATION HISTORY BUTTON */
  React.createElement('button', {
    className: 'conversation-history-btn',
    type: 'button',
    onClick: handleConversationHistory
  }, 'Conversation History'), /* STATUS BADGE */
  React.createElement('div', {
    className: 'stage-status-badge'
  }, rightBadge)));
}

/* =========================================================
INITIALIZE CUSTOM WIDGET
========================================================= */
appsmith.onReady(() => {
  ReactDOM.render(React.createElement(CommercialEvalHeader, null), document.getElementById('root'));
});

